import { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import SearchForm from '../components/SearchForm';
import RouteList from '../components/RouteList';
import { useNavigate } from 'react-router-dom';
import heroBg from '../hero-bg.jpg';
import '../styles/home.css';

const Home = () => {
  const [routes, setRoutes] = useState([]);
  const [filteredRoutes, setFilteredRoutes] = useState([]);
  const [searchParams, setSearchParams] = useState({ from: '', to: '', date: '' });
  const [isLoading, setIsLoading] = useState(true);
  const [isInitialSearch, setIsInitialSearch] = useState(true);
  const navigate = useNavigate();
  const resultsRef = useRef(null);
  const heroRef = useRef(null);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    
    const checkEmailConfirmation = () => {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.get('emailConfirmed')) {
        navigate('/', { replace: true });
        setTimeout(() => alert('✅ Email подтверждён!'), 300);
      }
    };

    const fetchRoutes = async () => {
      try {
        const { data } = await axios.get('/api/routes');
        setRoutes(data);
        setFilteredRoutes(data);
        setIsLoading(false);
      } catch (err) {
        console.error('Ошибка загрузки маршрутов:', err);
        setIsLoading(false);
      }
    };

    checkEmailConfirmation();
    fetchRoutes();
  }, [navigate]);

  const handleSearch = useCallback((params) => {
    const filtered = routes.filter(route => {
      const matchFrom = params.from ? route.from.toLowerCase().includes(params.from.toLowerCase()) : true;
      const matchTo = params.to ? route.to.toLowerCase().includes(params.to.toLowerCase()) : true;
      const routeDate = new Date(route.date);
      const searchDate = params.date ? new Date(params.date) : null;
      
      return matchFrom && matchTo && (!params.date || 
        routeDate.getFullYear() === searchDate.getFullYear() &&
        routeDate.getMonth() === searchDate.getMonth() &&
        routeDate.getDate() === searchDate.getDate());
    });

    setFilteredRoutes(filtered);
    setSearchParams(params);

    if (isInitialSearch) {
      setIsInitialSearch(false);
      setTimeout(() => {
        resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    }
  }, [routes, isInitialSearch]);

  const handleSearchReset = useCallback(() => {
    setIsInitialSearch(true);
    setSearchParams({ from: '', to: '', date: '' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <div className="home-page">
      {/* Hero Section - всегда видимая, но меняет высоту */}
      <section 
        ref={heroRef}
        className={`hero-section ${isInitialSearch ? '' : 'compact'}`}
        style={{ backgroundImage: `linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url(${heroBg})` }}
      >
        <div className="hero-overlay"></div>
        <div className="hero-content">
          <h1 className="hero-title">Найдите идеальное путешествие</h1>
          <p className="hero-subtitle">Откройте лучшие направления по выгодным ценам</p>
          
          {/* Форма только при первом поиске */}
          {isInitialSearch && (
            <div className="hero-search-container">
              <SearchForm 
                onSearch={handleSearch}
                initialValues={searchParams}
                wide={true}
                isLoading={isLoading}
              />
            </div>
          )}
        </div>
      </section>

      {/* Features Section - скрывается после поиска */}
      <section className={`features-wrapper ${isInitialSearch ? '' : 'hidden'}`}>
        <div className="features-container">
          <h2 className="features-title">Почему выбирают нас</h2>
          <div className="features-grid">
            {/* ... содержимое features ... */}
          </div>
        </div>
      </section>

      {/* Основной контент - появляется после поиска */}
      <section 
        className={`main-layout ${isInitialSearch ? 'hidden' : ''}`} 
        ref={resultsRef}
      >
        <div className="content-wrapper">
          <main className="main-content">
            <SearchForm 
              onSearch={handleSearch}
              initialValues={searchParams}
              wide={false}
              isLoading={isLoading}
            />
            <div className="routes-wrapper">
              {/* ... содержимое результатов ... */}
            </div>
          </main>
          {/* ... боковая панель ... */}
        </div>
      </section>
    </div>
  );
};

export default Home;
